-- SPDX-License-Identifier: AGPL-3.0-only
-- Team A model: κ-labels, κ-store, κ-map keys, verified materialization.
-- Analyzed source: hologram-ai @ c9609c0 (MIT OR Apache-2.0).
-- Catalog: functions/A_addressing.md (AD-01, AD-04..AD-08, AD-13, AD-15).
-- Alloy checks THIS MODEL, not the Rust. Every fact below is a reading of the
-- code; a wrong reading makes the result wrong. BLAKE3 collision resistance is
-- an ASSUMPTION (pred kappaInjective), never a fact: assertions that need it
-- say so in their antecedent.
module A_addressing

open util/ordering[Label] as LO

sig Blob {}
sig Label {}
-- AD-01 kappa_of: a total function Blob -> Label
one sig K { kappa: Blob -> one Label }

pred kappaInjective { all disj a, b: Blob | K.kappa[a] != K.kappa[b] }

-- A κ-map key (AD-09): the text between ':' and '@'. Not validated by the code.
abstract sig Key {}
sig LabelKey extends Key { lab: one Label }   -- a well-formed "blake3:<64 hex>"
sig Traversal extends Key {}                  -- e.g. "../../x" or "/abs/x"

abstract sig Loc {}
sig InStore extends Loc {}
sig Outside extends Loc {}

-- AD-05: root.join(k ++ ".bin")
one sig Join { at: Key -> one Loc }
fact joinShape {
  all k: LabelKey | Join.at[k] in InStore
  all k: Traversal | Join.at[k] in Outside
  all k1, k2: LabelKey | Join.at[k1] = Join.at[k2] iff k1.lab = k2.lab
}

sig FS { content: Loc -> lone Blob }

-- AD-05 DirKappaStore::resolve: read the joined file; no re-hash
pred resolve[fs: FS, k: Key, b: Blob] { fs.content[Join.at[k]] = b }

-- AD-08 non-bypass path: accept only content that hashes to the key
pred verifiedRead[fs: FS, k: LabelKey, b: Blob] {
  resolve[fs, k, b]
  K.kappa[b] = k.lab
}

-- AD-06 invalidate: remove the joined location, nothing else changes
pred invalidate[fs, fs2: FS, k: Key] {
  no fs2.content[Join.at[k]]
  all l: Loc - Join.at[k] | fs2.content[l] = fs.content[l]
}

-- AD-08 mismatch branch. A Traversal key is never a label, so its content
-- can never hash to it: the mismatch branch is always taken.
pred mismatchEvicts[fs, fs2: FS, k: Key, b: Blob] {
  resolve[fs, k, b]
  k in LabelKey implies K.kappa[b] != k.lab
  invalidate[fs, fs2, k]
}

-- AD-13 compose_model sorts its parts first; the composite is a function of
-- the sorted sequence. Lemma: two sorted sequences with equal multiplicities
-- are equal, so input order cannot matter.
sig Parts { s: seq Label }
pred sorted[q: seq Label] {
  all i: q.inds - q.lastIdx | LO/lte[q[i], q[plus[i, 1]]]
}
pred sameMultiset[a, b: seq Label] { all l: Label | #(a.l) = #(b.l) }

---------------------------------------------------------------- checks
-- AD-08 P1: a verified read returns the unique blob with that label
-- (needs the injectivity assumption).
assert materializeReturnsVerified {
  all fs: FS, k: LabelKey, b, b2: Blob |
    (kappaInjective and verifiedRead[fs, k, b] and K.kappa[b2] = k.lab) implies b = b2
}
check materializeReturnsVerified for 4

-- AD-06 fix witness: if every key were a well-formed label, eviction could
-- never touch a location outside the store.
assert validatedKeysStayInside {
  all fs, fs2: FS, k: LabelKey, b: Blob |
    mismatchEvicts[fs, fs2, k, b] implies (all o: Outside | fs2.content[o] = fs.content[o])
}
check validatedKeysStayInside for 4

-- AD-15 / 01-k-representation "equality of κ is equality of content",
-- under the assumption.
assert dedupIsIdentity {
  kappaInjective implies (all a, b: Blob | K.kappa[a] = K.kappa[b] iff a = b)
}
check dedupIsIdentity for 5

-- AD-13 P1
assert composeOrderFree {
  all p1, p2: Parts |
    (sorted[p1.s] and sorted[p2.s] and sameMultiset[p1.s, p2.s]) implies p1.s = p2.s
}
check composeOrderFree for 4 but 4 seq, 5 Int

---------------------------------------------------------------- runs
-- non-vacuity: a verified read exists
run someVerifiedRead { some fs: FS, k: LabelKey, b: Blob | verifiedRead[fs, k, b] } for 3
-- non-vacuity: two different orderings of the same parts sort to one sequence
run permutedPartsExist {
  some disj p1, p2: Parts, p3: Parts |
    #p1.s = 3 and p1.s != p2.s and sameMultiset[p1.s, p2.s] and sorted[p3.s]
    and sameMultiset[p3.s, p1.s]
} for 4 but 4 seq, 5 Int
-- GAP AD-05 P1: the store primitive returns content that does not hash to its key
run gap_storeResolveUnverified {
  some fs: FS, k: LabelKey, b: Blob | resolve[fs, k, b] and K.kappa[b] != k.lab
} for 3
-- GAP AD-06 P1: an unvalidated κ-map key deletes a file outside the store
run gap_traversalDeletesOutside {
  some fs, fs2: FS, k: Traversal, b: Blob |
    mismatchEvicts[fs, fs2, k, b] and some fs.content[Join.at[k]]
} for 3
-- GAP AD-08: a κ verified once in the session is trusted on a later read
-- (time-of-check / time-of-use between two reads)
run gap_secondReadTrusted {
  some fs1, fs2: FS, k: LabelKey, b1, b2: Blob |
    verifiedRead[fs1, k, b1] and resolve[fs2, k, b2] and K.kappa[b2] != k.lab
} for 3
-- GAP AD-01 P3: without the assumption, two contents can share a κ
run gap_dedupWithoutInjectivity { some disj a, b: Blob | K.kappa[a] = K.kappa[b] } for 3

-- SPDX-License-Identifier: AGPL-3.0-only
-- Team A model: Q4_0 / Q8_0 integer structure, Q4_0 layout vs GGML,
-- int8 per-channel encoding in scaled integers, compile-time quant strategy.
-- Analyzed source: hologram-ai @ c9609c0 (MIT OR Apache-2.0).
-- Catalog: functions/A_quant.md (QU-01, QU-03, QU-05, QU-07).
-- Alloy checks THIS MODEL, not the Rust. Integer-only. The encode checks
-- state the EXACT spec (rationals scaled to integers); the f32 code can move
-- Q by one step near ties (A_quant QU-05 (c)), so those UNSAT results do not
-- transfer to f32 without that error relation.
module A_quant

fun abs[x: Int]: Int { x < 0 implies minus[0, x] else x }

-------------------------------------------------- QU-01 nibble decode
-- byte b in [0,255]; lo = b mod 16, hi = b div 16; value = nibble - 8
pred isByte[b: Int] { b >= 0 and b <= 255 }
fun lo4[b: Int]: Int { minus[rem[b, 16], 8] }
fun hi4[b: Int]: Int { minus[div[b, 16], 8] }

assert nibbleRange {
  all b: Int | isByte[b] implies
    (lo4[b] >= -8 and lo4[b] <= 7 and hi4[b] >= -8 and hi4[b] <= 7)
}
check nibbleRange for 10 Int

-------------------------------------------------- QU-03 int8 decode
fun int8[b: Int]: Int { b < 128 implies b else minus[b, 256] }
assert int8Range { all b: Int | isByte[b] implies (int8[b] >= -128 and int8[b] <= 127) }
check int8Range for 10 Int

-------------------------------------------------- QU-01 layout
-- Output position p in [0,31] reads source (half, idx): half 0 = low nibble,
-- 1 = high nibble of qs[idx].
--   interleaved (q4_0.rs:20): p -> (p mod 2, p div 2)
--   GGML split  (ggml-quants.c:459): p -> (p div 16, p mod 16)
pred isPos[p: Int] { p >= 0 and p <= 31 }
fun iHalf[p: Int]: Int { rem[p, 2] }
fun iIdx[p: Int]: Int { div[p, 2] }
fun gHalf[p: Int]: Int { div[p, 16] }
fun gIdx[p: Int]: Int { rem[p, 16] }
pred sameSource[p: Int] { iHalf[p] = gHalf[p] and iIdx[p] = gIdx[p] }

-- The interleaved map is a bijection onto the 32 sources.
assert interleavedIsBijection {
  all p, q: Int | (isPos[p] and isPos[q] and iHalf[p] = iHalf[q] and iIdx[p] = iIdx[q]) implies p = q
}
check interleavedIsBijection for 7 Int
-- The two layouts read the same source only at positions 0 and 31, so the
-- outputs agree elementwise only where the block's nibble values happen to
-- coincide (the goldens differ on 27/16/28/4/0 of 32: checks/A_quant_layout.sh).
assert q4LayoutsDifferUnlessSymmetric {
  all p: Int | (isPos[p] and sameSource[p]) iff (p = 0 or p = 31)
}
check q4LayoutsDifferUnlessSymmetric for 7 Int

-------------------------------------------------- QU-05 encode (exact spec)
-- Scaled integers: w and amax are integers with 0 < amax and |w| <= amax.
-- Q = rhaz(127*w/amax) = sign(w) * floor((254*|w| + amax) / (2*amax)).
-- Exact claim |Q*s - w| <= s/2 with s = amax/127  <=>  |254*w - 2*Q*amax| <= amax.
pred encIn[w, amax: Int] { amax > 0 and amax <= 7 and abs[w] <= amax }
fun encQ[w, amax: Int]: Int {
  w < 0 implies minus[0, div[plus[mul[254, abs[w]], amax], mul[2, amax]]]
        else div[plus[mul[254, w], amax], mul[2, amax]]
}
assert encodeWithinRange {
  all w, amax: Int | encIn[w, amax] implies (encQ[w, amax] >= -127 and encQ[w, amax] <= 127)
}
check encodeWithinRange for 12 Int
assert encodeHalfStepBound {
  all w, amax: Int | encIn[w, amax] implies
    abs[minus[mul[254, w], mul[mul[2, encQ[w, amax]], amax]]] <= amax
}
check encodeHalfStepBound for 12 Int
assert encodeMaxIs127 {
  all w, amax: Int | (encIn[w, amax] and abs[w] = amax) implies abs[encQ[w, amax]] = 127
}
check encodeMaxIs127 for 12 Int

-------------------------------------------------- QU-07 quantize_weights
abstract sig Strategy {}
one sig SNone, SAuto, SQ4_0, SQ8_0, SQ2_0, SInt8, SInt4 extends Strategy {}
sig Graph { f32MatMulWeights: Int }          -- count of eligible inline f32 MatMul weights
sig Pass { strat: one Strategy, gIn, gOut: one Graph, err: lone ErrInt4 }
one sig ErrInt4 {}
-- reading of quantize.rs:31-35 and the Int8 loop
fact passSemantics {
  all p: Pass {
    p.strat = SInt4 implies some p.err
    p.strat != SInt4 implies no p.err
    p.strat = SInt8 implies p.gOut.f32MatMulWeights = 0
    p.strat not in SInt8 + SInt4 implies p.gOut = p.gIn
  }
  all g: Graph | g.f32MatMulWeights >= 0
}
assert nonInt8IsIdentity { all p: Pass | p.strat not in SInt8 + SInt4 implies p.gOut = p.gIn }
check nonInt8IsIdentity for 4 but 4 Int

run someInt8Rewrite { some p: Pass | p.strat = SInt8 and p.gIn.f32MatMulWeights > 0 } for 4 but 4 Int
-- GAP QU-07 P1: compiler.rs:195-197 documents Q4_0 compile-time quantization;
-- the pass leaves the graph unchanged.
run gap_q4_0DocumentedButNoop {
  some p: Pass | p.strat = SQ4_0 and p.gIn.f32MatMulWeights > 0 and p.gOut = p.gIn
} for 4 but 4 Int
-- non-vacuity for the layout facts: a position where the layouts read different sources
run gap_layoutMismatchPosition { some p: Int | isPos[p] and not sameSource[p] } for 7 Int
-- non-vacuity for encode: an input strictly inside the range
run encodeInstance { some w, amax: Int | encIn[w, amax] and w < 0 and abs[w] < amax } for 12 Int

-- SPDX-License-Identifier: AGPL-3.0-only
-- Team B reverse-engineering model of hologram-cnl + apps/hologram-api
-- Analyzed source: hologram-ai @ c9609c0 (MIT OR Apache-2.0)
--   crates/hologram-cnl/src/lib.rs:118-204 (compile_command; action scan 129-150, token loop 155-180), :40-49 (enforce_all)
--   apps/hologram-api/src/main.rs:115-170 (handle_request)
-- Integer-only model. Alloy checks this model, not the Rust.
module B_cnl_gate

abstract sig Bool {}
one sig True, False extends Bool {}

-- Lexer atoms: the arms of the token loop at lib.rs:155-180, value = prime from code.
abstract sig Tok { p: Int }
one sig TDeploy, TScale, TWebService, TCluster, TOn, TWith, TReplicas,
        TThree, TFive, TTwo, TTemperature, TZero, TMust, TBe, TRevoke, TIt, TAll extends Tok {}
fact tokValues {
  TDeploy.p = 2 and TScale.p = 3 and TWebService.p = 5 and TCluster.p = 7 and TOn.p = 5
  and TWith.p = 11 and TReplicas.p = 13 and TThree.p = 17 and TFive.p = 23 and TTwo.p = 29
  and TTemperature.p = 23 and TZero.p = 29 and TMust.p = 31 and TBe.p = 37 and TRevoke.p = 19
  and TIt.p = 5 and TAll.p = 1
}

-- A whitespace-separated word of the prompt.
--   lex   : the token after to_lowercase() (none = "Unknown token" error, lib.rs:178)
--   lower : the word is already lowercase, so the case-sensitive action scan
--           (tokens.contains(&"deploy") etc., lib.rs:129-150) sees it
--   isDestroy : the word is "destroy" -- present in LEXICON and in the action scan,
--               but there is no "destroy" arm in the token loop, so lex = none
sig Word { lex: lone Tok, lower: one Bool, isDestroy: one Bool }
fact destroyHasNoLexArm { all w: Word | w.isDestroy = True implies (no w.lex and w.lower = True) }

abstract sig Action {}
one sig AConfigTempZero, ADeploy, AScale, ADestroy, ARevoke, ANone extends Action {}

abstract sig Domain {}
one sig Legal, Medical, General extends Domain {}

one sig Req {
  words: seq Word,
  domain: one Domain
}

fun exactSeen[t: Tok]: set Word { { w: Req.words.elems | w.lower = True and w.lex = t } }

-- compile_command returns Err(..)
pred compileErr { Req.words.isEmpty or (some w: Req.words.elems | no w.lex) }

-- PhaseMirrorInvariants::enforce_all on StratumBoundary(ast): Err iff ast = Ap(1),
-- which happens iff the prompt is exactly one word lexing to p = 1 ("all").
pred diagnostic { not compileErr and #Req.words = 1 and Req.words.first.lex.p = 1 }

-- Action scan priority (lib.rs:129-150); temperature+zero first.
fun action: one Action {
  (some exactSeen[TTemperature] and some exactSeen[TZero]) => AConfigTempZero
  else (some exactSeen[TDeploy]) => ADeploy
  else (some exactSeen[TScale]) => AScale
  else (some w: Req.words.elems | w.isDestroy = True) => ADestroy
  else (some exactSeen[TRevoke]) => ARevoke
  else ANone
}

-- handle_request "hologram_generate" (main.rs:126-162): generation is allowed iff
-- compile_command is Ok and invariants_passed().
pred generationAllowed { not compileErr and not diagnostic }

-- B-CNL-1: a blocked (diagnostic) request never reaches generation. Holds by construction.
assert blockedNeverGenerates { diagnostic implies not generationAllowed }
check blockedNeverGenerates for 5 but 7 int, 4 seq expect 0

-- B-CNL-2: the gate blocks exactly the single-word prompt "all" (case-insensitive).
assert gateIsSingletonAll {
  (not compileErr and not generationAllowed) iff (#Req.words = 1 and Req.words.first.lex = TAll)
}
check gateIsSingletonAll for 5 but 7 int, 4 seq expect 0

-- B-CNL-3 (README claim "Temperature = 0.0" policy): allowed generation implies the
-- temperature-zero action. Refuted: e.g. "temperature 5", "deploy", "all all" pass.
assert temperaturePolicyEnforced { generationAllowed implies action = AConfigTempZero }
check temperaturePolicyEnforced for 5 but 7 int, 4 seq expect 1

-- B-CNL-4: domain-specific policy (ADR-001 "verifying temperature = 0.0 for specific
-- domains"). The domain never enters the gate, so this is refuted.
assert legalDomainRequiresTempZero {
  (generationAllowed and Req.domain = Legal) implies action = AConfigTempZero
}
check legalDomainRequiresTempZero for 5 but 7 int, 4 seq expect 1

-- B-CNL-5: the Destroy action can never be allowed (no lexer arm). Non-vacuity style run
-- that is expected to have NO instance.
pred destroyAllowed { generationAllowed and action = ADestroy }
run destroyAllowed for 5 but 7 int, 4 seq expect 0

-- Non-vacuity runs.
pred someBlocked { diagnostic }
run someBlocked for 5 but 7 int, 4 seq expect 1
pred someAllowedNonZeroTemp { generationAllowed and action != AConfigTempZero }
run someAllowedNonZeroTemp for 5 but 7 int, 4 seq expect 1

-- SPDX-License-Identifier: AGPL-3.0-only
-- Team B model: the honesty meta-gate (model validate + honesty audit) and the BDD runner.
-- Analyzed source: hologram-ai @ c9609c0 (MIT OR Apache-2.0)
--   crates/hologram-ai-model/src/lib.rs:231 (validate), crates/hologram-ai-model/src/honesty.rs:43 (audit)
--   crates/hologram-ai-conformance/tests/bdd.rs main (~4960+): fail_on_skipped, "selected features ran"
--   scripts/anti-hardcode.sh (file globs, stop at first #[cfg(test)])
-- No integers needed. Alloy checks this model, not the Rust/shell.
module B_conformance

abstract sig Level {}
one sig Verified, Build, Open extends Level {}
abstract sig Exec {}
one sig Rust, Browser extends Exec {}
abstract sig YN {}
one sig Y, N extends YN {}

sig Oracle { independent: one YN }        -- authored outside this repo AND outside its substrate
sig Step { defined: one YN, checksThen: one YN }
sig Feature { stepSet: some Step, tagsOk: one YN, skipTag: one YN, targetTag: one YN }
sig Row {
  level: one Level, exec: one Exec, defaultLane: one YN,
  oracles: set Oracle, consulted: set Oracle, feature: one Feature
}
fact { all r: Row | r.consulted in r.oracles }
fact { all f: Feature | some feature.f }            -- honesty: every on-disk feature is claimed

pred gating[r: Row] { r.level in Verified + Build }
-- lib.rs validate (subset relevant here): non-empty known oracles per row
pred validateOk { all r: Row | some r.oracles }
-- honesty.rs audit: tags present; suite rows carry no skip tags; target rows carry @target;
-- open rows are non-gating (true by construction of `gating`)
pred auditOk {
  all r: Row | r.feature.tagsOk = Y
  all r: Row | gating[r] implies r.feature.skipTag = N and r.feature.targetTag = N
  all r: Row | r.level = Open implies r.feature.targetTag = Y
}
-- default-lane runner: selects rust/default-lane features without @target; any undefined
-- step is "skipped" and fails the run (fail_on_skipped + skipped == 0 assert)
fun selected: set Row { { r: Row | r.exec = Rust and r.defaultLane = Y and r.feature.targetTag = N } }
pred runnerGreen { all r: selected, s: r.feature.stepSet | s.defined = Y }

-- B-CF-1: the meta-gate implies every gating feature's stepSet are defined. Refuted: the
-- audit never looks at step definitions.
assert gateImpliesStepsDefined {
  (validateOk and auditOk) implies (all r: Row | gating[r] implies (all s: r.feature.stepSet | s.defined = Y))
}
check gateImpliesStepsDefined for 4 expect 1

-- B-CF-2: the meta-gate implies each gating row cites an independent authority. Refuted:
-- any known oracle id passes, including the self-authored journey-reference.
assert gateImpliesIndependentAuthority {
  (validateOk and auditOk) implies (all r: Row | gating[r] implies some r.oracles & independent.Y)
}
check gateImpliesIndependentAuthority for 4 expect 1

-- B-CF-3: the meta-gate implies the cited authority is actually consulted by step code. Refuted.
assert gateImpliesConsulted {
  (validateOk and auditOk) implies (all r: Row | r.oracles in r.consulted)
}
check gateImpliesConsulted for 4 expect 1

-- B-CF-4: a green default-lane run implies every selected feature's stepSet are defined.
assert greenImpliesDefined { runnerGreen implies (all r: selected, s: r.feature.stepSet | s.defined = Y) }
check greenImpliesDefined for 4 expect 0

-- B-CF-5: a green run implies each Then really checks its postcondition. Refuted: a step
-- that only prints (e.g. the @target "reported, never asserted" rows when selected) passes.
assert greenImpliesThenChecked { runnerGreen implies (all r: selected, s: r.feature.stepSet | s.checksThen = Y) }
check greenImpliesThenChecked for 4 expect 1

pred gateNonVacuous { validateOk and auditOk and runnerGreen and some selected }
run gateNonVacuous for 4 expect 1

------------------------------------------------------------------------
-- anti-hardcode.sh: scanned file set and the "stop at first #[cfg(test)]" cut
------------------------------------------------------------------------
sig SrcFile { scanned: one YN, hasModelConstant: one YN, constantBeforeCfgTest: one YN }
pred antiHardcodePasses { all f: SrcFile | (f.scanned = Y and f.hasModelConstant = Y) implies f.constantBeforeCfgTest = N }
-- B-CF-6: passing anti-hardcode implies no model-specific constant in non-test source.
-- Refuted: only safetensors/src/*.rs and wasm/src/*.rs are scanned (plus web URL patterns).
assert antiHardcodeComplete {
  antiHardcodePasses implies (no f: SrcFile | f.hasModelConstant = Y and f.constantBeforeCfgTest = Y)
}
check antiHardcodeComplete for 3 expect 1

-- SPDX-License-Identifier: AGPL-3.0-only
-- Team B model: content-addressed elision, stage residency, session verified-κ set,
-- derived-stage store.
-- Analyzed source: hologram-ai @ c9609c0 (MIT OR Apache-2.0)
--   crates/hologram-ai/src/staged.rs:437-508 (StagedRunner::execute_window)
--   crates/hologram-ai/src/staged.rs:942-980 (stages_for_window), :861-898 (DirDerivedStore)
--   crates/hologram-ai/src/materialize.rs:229-371 (materialize_archive_with / patch_constants)
--   upstream hologram-exec @ 18f553d8 crates/hologram-exec/src/session.rs ~730-790 (reuse rule)
-- Integer-only (byte counts are small integers). Labels/κ are abstract atoms; the hash is
-- modelled as a function, collision-freedom is stated where an assertion needs it.
-- Alloy checks this model, not the Rust.
module B_elision_cache

open util/ordering[Stage] as SO   -- note: makes the Stage scope exact (4 stages)

------------------------------------------------------------------------
-- Part 1: one execute_window pass over ordered stages with a residency budget
------------------------------------------------------------------------
sig Stage {
  bytes: Int,                 -- stage_weight_bytes[stage] (counted on materialization)
  resBefore: set Stage,          -- resident set when this stage starts, after take() of itself
  admitted: lone Stage,       -- = this stage iff admissible
  probeOk: lone Stage,        -- admission_probe(margin) result for this stage (free)
  peakAfter: Int              -- peak_resident_weight_bytes after this stage
}
one sig Budget { b: Int, start: set Stage, peak0: Int }

fun rsum[X: set Stage]: Int { sum s: X | s.bytes }
fun resAfter[s: Stage]: set Stage { s.resBefore + s.admitted }
fun imax[a, c: Int]: Int { (a >= c) => a else c }

fact passSemantics {
  all s: Stage | s.bytes >= 0 and s.bytes =< 7
  Budget.b >= 0 and Budget.b =< 15 and Budget.peak0 >= 0 and Budget.peak0 =< 15
  rsum[Budget.start] =< Budget.b               -- invariant carried from earlier passes
  all s: Budget.start | s.bytes > 0            -- only admitted (bytes > 0) stages are resident
  -- first stage: resident = start minus itself (take())
  SO/first.resBefore = Budget.start - SO/first
  all s: Stage - SO/last | SO/next[s].resBefore = resAfter[s] - SO/next[s]
  -- admissible = bytes > 0 && resident + bytes <= budget && probe(margin)
  all s: Stage | (s.admitted = s) iff
      (s.bytes > 0 and plus[rsum[s.resBefore], s.bytes] =< Budget.b and s.probeOk = s)
  all s: Stage | s.admitted in s and s.probeOk in s
  -- peak = max(peak, max(resident_bytes, bytes))  (staged.rs:500-502)
  SO/first.peakAfter = imax[Budget.peak0, imax[rsum[resAfter[SO/first]], SO/first.bytes]]
  all s: Stage - SO/last | let n = SO/next[s] |
      n.peakAfter = imax[s.peakAfter, imax[rsum[resAfter[n]], n.bytes]]
}
-- weight bytes alive while stage s executes: the other resident stages plus s itself
fun live[s: Stage]: Int { plus[rsum[s.resBefore], s.bytes] }
-- s was materialized this pass iff it was not resident at the start
pred materialized[s: Stage] { s not in Budget.start }

-- B-EC-1: resident bytes never exceed the budget.
assert residentWithinBudget { all s: Stage | rsum[resAfter[s]] =< Budget.b }
check residentWithinBudget for 4 but 6 int expect 0

-- B-EC-2: recorded peak >= true live weight bytes. Refuted: a non-admitted stage that runs
-- while other stages are resident is counted as max(resident, bytes), not resident + bytes.
assert recordedPeakCoversLive { all s: Stage | SO/last.peakAfter >= live[s] }
check recordedPeakCoversLive for 4 but 6 int expect 1

-- B-EC-3: true live bytes <= budget + this stage's bytes (the bound that does hold).
assert liveBounded { all s: Stage | live[s] =< plus[Budget.b, s.bytes] }
check liveBounded for 4 but 6 int expect 0

-- B-EC-4 (stage_residency_cache.feature, zero budget): nothing is ever resident, so every
