pred inRange[m, wantTop: Int] {
  P.mx >= 1 and P.mx =< plus[plus[m, m], plus[m, m]]
  and P.want >= 1 and P.want =< wantTop and P.want2 >= 1 and P.want2 =< wantTop
  and P.cur >= 0 and P.cur =< P.mx
}


