-- SPDX-License-Identifier: AGPL-3.0-only
-- Team B model: native tokenizer special-token handling (eos/bos resolution, decode filter).
-- Analyzed source: hologram-ai @ c9609c0 (MIT OR Apache-2.0)
--   crates/hologram-ai-tokenizer/src/native.rs:311-338 (encode/decode), :364-399 (parse_special_tokens)
--   crates/hologram-ai/src/commands/generate.rs:307 (eos = cfg.eos or tokenizer.eos_token_id())
-- Integer ids as atoms; the BPE/unigram merge procedures are not modelled here (they are
-- specified as total functions in functions/B_tokenizer.md). Alloy checks this model, not the Rust.
module B_tokenizer

sig Id {}
one sig Id2 extends Id {}                       -- the literal default `eos_id.unwrap_or(2)`
abstract sig Content {}
one sig LtS, EndS, Unk, Pad, OtherSpecial extends Content {}   -- "<s>", "</s>", "<unk>", "<pad>", other
sig Added { id: one Id, content: one Content }  -- tokenizer.json added_tokens
one sig Tok {
  normal: set Id,                               -- ids of ordinary vocabulary pieces
  declaredEos: one Id                           -- the model's real EOS (generation_config / tokenizer_config)
}
-- parse_special_tokens: a "</s>" entry sets eos, otherwise 2; "<s>" sets bos. Later entries
-- with the same content overwrite earlier ones (loop order); modelled as "some entry".
fun eosId: one Id { (some a: Added | a.content = EndS) => { a: Added | a.content = EndS }.id else Id2 }
fun bosId: lone Id { { a: Added | a.content = LtS }.id }
fact oneEntryPerContent { all c: LtS + EndS | lone content.c }
fact addedNotNormal { no Added.id & Tok.normal }

-- decode filters bos and eos before decode_raw
fun keptByDecode[ids: set Id]: set Id { ids - eosId - bosId }

-- B-TK-1: the EOS used by generation is the model's declared EOS. Refuted whenever the
-- declared EOS is not spelled "</s>" (e.g. "<|endoftext|>", "<|im_end|>"): eos falls back to 2.
assert eosIsDeclared { eosId = Tok.declaredEos }
check eosIsDeclared for 4 expect 1

-- B-TK-2: decode never drops an ordinary vocabulary piece. Refuted when the fallback id 2 is
-- an ordinary piece: decode filters it (and generation stops on it).
assert decodeKeepsNormal { keptByDecode[Tok.normal] = Tok.normal }
check decodeKeepsNormal for 4 expect 1

-- B-TK-3: when "</s>" is an added token, decode keeps every ordinary piece.
assert decodeKeepsNormalWithEndS {
  (some a: Added | a.content = EndS) implies keptByDecode[Tok.normal] = Tok.normal
}
check decodeKeepsNormalWithEndS for 4 expect 0

pred tokNonVacuous { some Tok.normal and some a: Added | a.content = EndS }
run tokNonVacuous for 4 expect 1

-- SPDX-License-Identifier: AGPL-3.0-only
-- Team B model: regex pre-tokenizer (split_fragments) fragment partition.
-- DRAFT - NOT YET RUN: no JVM/Alloy on the drafting machine; run via
--   ./run-B.sh  (Alloy checks this model, not the Rust).
-- Analyzed source: hologram-re/oracle/crates/hologram-ai-regex (RegexSplitter,
-- verbatim split_fragments logic stripped from hologram-ai-tokenizer).
-- Original: BpeEncoder::split_fragments, hologram-ai @ c9609c0 (MIT OR Apache-2.0)
module B_tokenizer_regex

-- The text being split, as a character sequence.
sig Char {}
one sig Input { chars: seq Char }

-- A fragment is a half-open range [start, end) into Input.chars.
sig Frag { start: Int, end: Int }

-- The compiled-regex handle. NONE means the pattern failed to compile and the
-- splitter is in pass-through (mirrors Regex::new(pattern).ok() -> None ->
-- vec![text]; the classic GPT-2 pattern's \s+(?!\S) negative look-ahead fails
-- on regex-automata and lands exactly here).
sig CompiledRe {}

one sig Splitter {
  re: lone CompiledRe,
  frags: seq Frag
}{
  -- R-1: fallback is the identity: exactly one fragment, the whole text.
  no re implies (#frags = 1 and frags[0].start = 0 and frags[0].end = #(Input.chars))
  -- R-2: a compiled regex tiles the input with nonempty fragments;
  -- empty input legitimately yields zero fragments (see test
  -- empty_text_yields_no_fragments in hologram-ai-regex).
  some re implies (orderedTile[frags] or (no frags and no Input.chars))
}

fact fragRanges {
  all f: Frag {
    f.start >= 0
    f.end <= #(Input.chars)
    f.start < f.end                    -- find_iter yields nonempty matches
  }
}

-- The fragment ranges are contiguous, gap-free and cover the whole input.
pred orderedTile[f: seq Frag] {
  #(f) >= 1
  f[0].start = 0
  f[f.last].end = #(Input.chars)
  all i: f.butlast.inds | f[i].end = f[i.next].start
}

-- B-TK-R1: fallback never fabricates fragments: exactly one, the whole text.
assert fallbackIsIdentity {
  all s: Splitter | no s.re implies (#(s.frags) = 1 and s.frags[0].start = 0 and s.frags[0].end = #(Input.chars))
}
check fallbackIsIdentity for 5 expect 0

-- B-TK-R2: compiled splits are total and gap-free (or empty on empty input).
assert compiledSplitsTile {
  all s: Splitter | some s.re implies (orderedTile[s.frags] or (no s.frags and no Input.chars))
}
check compiledSplitsTile for 5 expect 0

-- gap_lookaheadFailsToCompile: witness the unmodeled hazard - a splitter whose
-- pattern did not compile sits in silent pass-through. SAT means the hazard is
-- expressible (mirrors the classic GPT-2 look-ahead failing on regex-automata).
pred gap_lookaheadFailsToCompile { some s: Splitter | no s.re }
run gap_lookaheadFailsToCompile for 5 expect 1

-- Non-vacuity: a compiled split into more than one fragment exists.
pred splitNonVacuous { some s: Splitter | some s.re and #(s.frags) > 1 }
run splitNonVacuous for 5 expect 1

-- SPDX-License-Identifier: AGPL-3.0-only
-- Team B model: geometric_window with the real MIN_WINDOW = 64, at 10-bit Int.
-- Analyzed source: hologram-ai @ c9609c0 (MIT OR Apache-2.0), crates/hologram-ai/src/engine.rs:37-52
-- Kept in its own module and split into small asserts: at 10-bit Int each check needs
-- roughly 15-60 s with SAT4J/MiniSat on this box. Alloy checks this model, not the Rust.
module B_window64

fun clampWant[want, mx: Int]: Int { (want < 1) => 1 else ((want > mx) => mx else want) }
fun bucketAtLeast64[c: Int]: Int { (c =< 64) => 64 else ((c =< 128) => 128 else 256) }
fun geo64[want, mx: Int]: Int { let b = bucketAtLeast64[clampWant[want, mx]] | (b < mx) => b else mx }

one sig P { want, mx: Int }
-- max_window in [1, 256] so the bucket list 64,128,256 is complete; want in [1, 300].
pred inRange { P.mx >= 1 and P.mx =< 256 and P.want >= 1 and P.want =< 300 }

-- B-GEN-1a: window <= max_window.
assert geoLeMax_m64 { inRange implies geo64[P.want, P.mx] =< P.mx }
check geoLeMax_m64 for 1 but 10 int expect 0

-- B-GEN-1b: want <= max_window  =>  window >= want.
assert geoCoversWant_m64 { (inRange and P.want =< P.mx) implies geo64[P.want, P.mx] >= P.want }
check geoCoversWant_m64 for 1 but 10 int expect 0

-- B-GEN-1c: want > max_window  =>  window = max_window (silent cap, no error).
assert geoCapsAtMax_m64 { (inRange and P.want > P.mx) implies geo64[P.want, P.mx] = P.mx }
check geoCapsAtMax_m64 for 1 but 10 int expect 0

-- B-GEN-1d: the window is one of 64, 128, 256 or exactly max_window.
assert geoIsBucketOrCap_m64 { inRange implies geo64[P.want, P.mx] in (64 + 128 + 256 + P.mx) }
check geoIsBucketOrCap_m64 for 1 but 10 int expect 0

pred nonVacuous64 { inRange and P.want = 65 and P.mx = 200 and geo64[P.want, P.mx] = 128 }
run nonVacuous64 for 1 but 10 int expect 1
